--- HTTP Listener Module for Virtual CLU
-- This module provides HTTP server/listener functionality compatible with Object Manager.
-- It allows receiving HTTP requests on specified paths and sending responses.
-- Uses the embedded HTTPServer for handling incoming requests.
--
-- @module HTTPListener
-- @author Autogenerated code: HTTPListener, interface: object_http_listener_v1.xml
-- @usage
--   local listener = HTTPListener:new("listener1", "192.168.1.100", eventBus)
--   listener:set(HTTPListener.FEATURE_PATH, "/api/webhook")
--   listener:add_event(HTTPListener.EVENT_ON_REQUEST, function()
--       local body = listener:get(HTTPListener.FEATURE_REQUEST_BODY)
--       listener:set(HTTPListener.FEATURE_RESPONSE_BODY, "OK")
--       listener:execute(HTTPListener.METHOD_SEND_RESPONSE)
--   end)

HTTPListener = {}

-- ============================================
-- Feature Constants
-- ============================================

--- Path feature constant (settable)
-- URL path to listen on (e.g., "/api/webhook")
HTTPListener.FEATURE_PATH = 0

--- Method feature constant (read-only)
-- HTTP method received in request (GET, POST, etc.)
HTTPListener.FEATURE_METHOD = 1

--- Query string parameters feature constant (read-only in scripts)
-- Returns HTTP query parameters as table
HTTPListener.FEATURE_QUERY_STRING_PARAMS = 2

--- Request type feature constant (read-only)
-- Type of received request:
-- 0 - None, 1 - Text, 2 - JSON, 3 - XML, 4 - FormData, 5 - Other
HTTPListener.FEATURE_REQUEST_TYPE = 3

--- Request body feature constant (read-only in scripts)
-- Body content of received HTTP request
HTTPListener.FEATURE_REQUEST_BODY = 5

--- Response type feature constant (settable)
-- Type of response to send:
-- 0 - None, 1 - Text, 2 - JSON, 3 - XML, 4 - FormData
HTTPListener.FEATURE_RESPONSE_TYPE = 6

--- Response body feature constant (settable)
-- Body content to send in response
HTTPListener.FEATURE_RESPONSE_BODY = 8

--- Status code feature constant (settable)
-- HTTP status code to send (default 200)
HTTPListener.FEATURE_STATUS_CODE = 9

-- ============================================
-- Request/Response Type Constants
-- ============================================

HTTPListener.TYPE_NONE = 0
HTTPListener.TYPE_TEXT = 1
HTTPListener.TYPE_JSON = 2
HTTPListener.TYPE_XML = 3
HTTPListener.TYPE_FORM_DATA = 4
HTTPListener.TYPE_OTHER = 5

-- ============================================
-- Method Constants
-- ============================================

--- Send response to the received request
HTTPListener.METHOD_SEND_RESPONSE = 0

--- Clear response data
HTTPListener.METHOD_CLEAR = 1

-- ============================================
-- Event Constants
-- ============================================

--- Event triggered when HTTP request is received
HTTPListener.EVENT_ON_REQUEST = 0

-- ============================================
-- Content-Type mappings
-- ============================================

HTTPListener._contentTypes = {
    [0] = nil,                                      -- None
    [1] = "text/plain",                             -- Text
    [2] = "application/json",                       -- JSON
    [3] = "text/xml",                               -- XML
    [4] = "application/x-www-form-urlencoded",     -- FormData
    [5] = nil,                                      -- Other
}

-- ============================================
-- Instance registry (for routing requests)
-- ============================================

HTTPListener._instances = {}

--- Create a new HTTPListener instance
-- @param id string Unique identifier for this listener
-- @param address string Network address (optional)
-- @param eventBus table Event bus instance for event handling
-- @return table New HTTPListener instance
function HTTPListener:new(id, address, eventBus)
    if id == nil then
        error("HTTPListener: missing id")
    end

    if eventBus == nil then
        error("HTTPListener: missing eventBus")
    end

    local listener = {
        id = id,
        description = "HTTPListener",
        address = address,
        eventBus = eventBus,

        -- Configuration
        path = "",
        responseType = HTTPListener.TYPE_TEXT,
        responseBody = "",
        statusCode = 200,

        -- Request data (populated when request arrives)
        method = "",
        queryStringParams = {},
        requestType = HTTPListener.TYPE_NONE,
        requestBody = "",
        requestHeaders = {},

        -- Internal state
        _registered = false,
        _pendingRequestId = nil,
    }

    setmetatable(listener, self)
    self.__index = self

    -- Register in global instances
    HTTPListener._instances[id] = listener

    return listener
end

--- Register this listener with the HTTP server
-- Called automatically when path is set
function HTTPListener:_register()
    if self._registered then
        self:_unregister()
    end

    if not self.path or self.path == "" then
        return
    end

    local self_ref = self

    -- Register endpoint with HTTPServer
    HTTPServer:on(self.path, "GET,POST,PUT,DELETE,PATCH", function(req)
        -- Store request data
        self_ref.method = req.method or ""
        self_ref.queryStringParams = req.query or {}
        self_ref.requestBody = req.body or ""
        self_ref.requestHeaders = req.headers or {}
        self_ref._pendingRequestId = req.id

        -- Detect request type from Content-Type header
        self_ref.requestType = self_ref:_detectRequestType(req.headers)

        -- Parse body based on request type
        self_ref:_parseRequestBody()

        Logger:getShared():debug("[HTTPListener] %s: received %s %s", self_ref.id, req.method, req.path)

        -- Fire OnRequest event - user should call SendResponse in handler
        self_ref.eventBus:fire(self_ref, HTTPListener.EVENT_ON_REQUEST)

        -- If user didn't send response, send default
        if self_ref._pendingRequestId then
            return {
                status = self_ref.statusCode,
                body = self_ref:_serializeResponseBody(),
                headers = self_ref:_buildResponseHeaders()
            }
        end

        -- Response already sent via SendResponse
        return nil
    end)

    self._registered = true
    Logger:getShared():info("[HTTPListener] %s: registered on path %s", self.id, self.path)
end

--- Unregister this listener from the HTTP server
function HTTPListener:_unregister()
    if not self._registered then
        return
    end

    if self.path and self.path ~= "" then
        HTTPServer:off(self.path)
    end

    self._registered = false
end

--- Detect request type from Content-Type header
-- @param headers table Request headers
-- @return number Request type constant
function HTTPListener:_detectRequestType(headers)
    local contentType = headers["Content-Type"] or headers["content-type"] or ""
    contentType = contentType:lower()

    if contentType:find("application/json") then
        return HTTPListener.TYPE_JSON
    elseif contentType:find("text/xml") or contentType:find("application/xml") then
        return HTTPListener.TYPE_XML
    elseif contentType:find("application/x%-www%-form%-urlencoded") then
        return HTTPListener.TYPE_FORM_DATA
    elseif contentType:find("text/plain") then
        return HTTPListener.TYPE_TEXT
    elseif contentType == "" then
        return HTTPListener.TYPE_NONE
    else
        return HTTPListener.TYPE_OTHER
    end
end

--- Parse request body based on request type
function HTTPListener:_parseRequestBody()
    local body = self.requestBody

    if self.requestType == HTTPListener.TYPE_JSON then
        if JSON and JSON.decode and body and body ~= "" then
            local ok, parsed = pcall(JSON.decode, body)
            if ok and parsed then
                self.requestBody = parsed
            end
        end
    elseif self.requestType == HTTPListener.TYPE_FORM_DATA then
        if body and body ~= "" then
            local parsed = {}
            for pair in body:gmatch("[^&]+") do
                local key, value = pair:match("([^=]+)=?(.*)")
                if key then
                    -- URL decode
                    key = key:gsub("%%(%x%x)", function(h) return string.char(tonumber(h, 16)) end)
                    value = (value or ""):gsub("%%(%x%x)", function(h) return string.char(tonumber(h, 16)) end)
                    parsed[key] = value
                end
            end
            self.requestBody = parsed
        end
    end
    -- For Text, XML, None, Other - keep as string
end

--- Serialize response body based on response type
-- @return string Serialized response body
function HTTPListener:_serializeResponseBody()
    local body = self.responseBody

    if body == nil then
        return ""
    end

    if self.responseType == HTTPListener.TYPE_JSON and type(body) == "table" then
        if JSON and JSON.encode then
            return JSON.encode(body)
        end
    elseif self.responseType == HTTPListener.TYPE_FORM_DATA and type(body) == "table" then
        local parts = {}
        for k, v in pairs(body) do
            table.insert(parts, tostring(k) .. "=" .. tostring(v))
        end
        return table.concat(parts, "&")
    end

    return tostring(body)
end

--- Build response headers
-- @return table Response headers
function HTTPListener:_buildResponseHeaders()
    local headers = {}

    local contentType = HTTPListener._contentTypes[self.responseType]
    if contentType then
        headers["Content-Type"] = contentType
    end

    return headers
end

--- Set a feature value
-- @param key number Feature constant
-- @param value any Value to set
-- @return table Self for method chaining
function HTTPListener:set(key, value)
    if value == nil then
        error("HTTPListener:set(" .. key .. ", nil)")
    end

    if key == HTTPListener.FEATURE_PATH then
        self.path = value
        self:_register()
        return self
    end

    if key == HTTPListener.FEATURE_RESPONSE_TYPE then
        if value < 0 or value > 4 then
            error("HTTPListener: ResponseType must be 0-4")
        end
        self.responseType = value
        return self
    end

    if key == HTTPListener.FEATURE_RESPONSE_BODY then
        self.responseBody = value
        return self
    end

    if key == HTTPListener.FEATURE_STATUS_CODE then
        self.statusCode = value
        return self
    end

    -- Read-only features (set internally)
    if key == HTTPListener.FEATURE_QUERY_STRING_PARAMS then
        self.queryStringParams = value
        return self
    end

    if key == HTTPListener.FEATURE_REQUEST_BODY then
        self.requestBody = value
        return self
    end

    error("HTTPListener: unknown feature key: " .. tostring(key))
end

--- Get a feature value
-- @param key number Feature constant
-- @return any Feature value
function HTTPListener:get(key)
    if key == HTTPListener.FEATURE_PATH then
        return self.path
    end

    if key == HTTPListener.FEATURE_METHOD then
        return self.method
    end

    if key == HTTPListener.FEATURE_QUERY_STRING_PARAMS then
        return self.queryStringParams
    end

    if key == HTTPListener.FEATURE_REQUEST_TYPE then
        return self.requestType
    end

    if key == HTTPListener.FEATURE_REQUEST_BODY then
        return self.requestBody
    end

    if key == HTTPListener.FEATURE_RESPONSE_TYPE then
        return self.responseType
    end

    if key == HTTPListener.FEATURE_RESPONSE_BODY then
        return self.responseBody
    end

    if key == HTTPListener.FEATURE_STATUS_CODE then
        return self.statusCode
    end

    error("HTTPListener: unknown feature key: " .. tostring(key))
end

--- Execute a method
-- @param key number Method constant
-- @param value any Optional parameter
function HTTPListener:execute(key, value)
    if key == HTTPListener.METHOD_SEND_RESPONSE then
        Logger:getShared():debug("[HTTPListener] %s: SendResponse (status=%d)", self.id, self.statusCode)

        -- Response is returned from the handler function
        -- This method is mainly for compatibility - the actual response
        -- is handled in the _register callback
        self._pendingRequestId = nil
        return
    end

    if key == HTTPListener.METHOD_CLEAR then
        self.responseBody = ""
        self.statusCode = 200
        self.responseType = HTTPListener.TYPE_TEXT
        return
    end

    error("HTTPListener: unknown method key: " .. tostring(key))
end

--- Register an event callback
-- @param eventName number Event constant
-- @param callback function Callback function
function HTTPListener:add_event(eventName, callback)
    self.eventBus:on(self, eventName, callback)
end

--- Get current state as table
-- @return table Object state
function HTTPListener:__getState()
    return {
        id = self.id,
        address = self.address,
        type = 'HTTPListener',
        path = self.path,
        method = self.method,
        queryStringParams = self.queryStringParams,
        requestType = self.requestType,
        requestBody = self.requestBody,
        responseType = self.responseType,
        responseBody = self.responseBody,
        statusCode = self.statusCode,
        registered = self._registered,
    }
end

--- Cleanup when listener is destroyed
function HTTPListener:destroy()
    self:_unregister()
    HTTPListener._instances[self.id] = nil
end

return HTTPListener
